import assert from 'assert';
import { test } from 'node:test';
import * as neon from './game/neon.js';

test('D1: Missing bounce - Ball should bounce off the top of a brick', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0]; // Row 0, Col 0

  // Position ball just above the brick, moving down
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - neon.BALL_R - 1;
  state.ball.vx = 0;
  state.ball.vy = 200; // Moving DOWN

  // We simulate one frame.
  // In the real game, step() happens, then frame() checks collisions.
  const dt = 0.01;
  neon.step(state, dt);

  // Now we simulate the collision check that's currently in frame()
  // Since we can't call frame() without a canvas, we'll manually 
  // replicate the logic that is currently there.
  if (neon.collides(state.ball, brick)) {
    brick.alive = false;
    // The bug: no velocity change happens here in the current code
  }

  // Expected: vy should be negative (UP)
  // Actual: vy remains 200
  assert.strictEqual(Math.sign(state.ball.vy), neon.UP, `Ball should have bounced UP, but vy is ${state.ball.vy}`);
});

test('D2: Sticky collision - Naive fix (just flipping vy) causes vibration', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0];

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 1; // Already overlapping
  state.ball.vx = 0;
  state.ball.vy = 200;

  // Naive fix: just flip vy if colliding
  const simulateNaiveFrame = () => {
    if (neon.collides(state.ball, brick)) {
      state.ball.vy *= -1;
    }
  };

  simulateNaiveFrame();
  const vy1 = state.ball.vy;
  simulateNaiveFrame();
  const vy2 = state.ball.vy;

  // If it's sticky, vy will flip back and forth
  assert.notStrictEqual(vy1, vy2, 'Ball should not flip velocity back and forth if it stays overlapping');
});

test('D3: Face vs Coin - Corner hit should flip both axes', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0];

  // Position ball so it hits the top-left corner
  state.ball.x = brick.x - neon.BALL_R / 2;
  state.ball.y = brick.y - neon.BALL_R / 2;
  state.ball.vx = 200; 
  state.ball.vy = 200;

  // Current collision check
  if (neon.collides(state.ball, brick)) {
    // Naive fix might only flip the axis of most penetration
    // But a corner hit should flip both.
  }

  // This test is for the final fix. I'll refine it once I implement.
});

