import assert from 'assert';
import { test } from 'node:test';
import * as neon from '../game/neon.js';

// Helper to simulate the current logic of frame()
function simulateCollision(state, brick) {
  if (neon.collides(state.ball, brick)) {
    brick.alive = false;
    // BUG: No bounce here
  }
}

// Helper to simulate a NAIVE fix (just flipping Y)
function simulateNaiveCollision(state, brick) {
  if (neon.collides(state.ball, brick)) {
    brick.alive = false;
    state.ball.vy *= -1;
  }
}

test('D1: Missing bounce - Ball should flip velocity on hit', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - neon.BALL_R - 1;
  state.ball.vy = 200;

  simulateCollision(state, brick);
  assert.strictEqual(Math.sign(state.ball.vy), neon.UP, 'Ball should have bounced UP');
});

test('D2: Sticky collision - Naive fix leads to vibration', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 1; // Overlapping
  state.ball.vy = 200;

  // First hit
  simulateNaiveCollision(state, brick);
  const vy1 = state.ball.vy;

  // Second hit (still overlapping)
  simulateNaiveCollision(state, brick);
  const vy2 = state.ball.vy;

  assert.notStrictEqual(vy1, vy2, 'Ball should not vibrate between frames');
});

test('D3: Double inversion - Naive fix fails at seams', () => {
  const state = neon.createState(1);
  const bricks = neon.makeBricks(1);
  const b1 = bricks[0]; // Row 0, Col 0
  const b2 = bricks[1]; // Row 0, Col 1

  // Position ball exactly on the seam between b1 and b2
  state.ball.x = b1.x + b1.w; 
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 200;
  state.ball.vy = 0;

  // Naive fix: flip vx for each collision
  const simulateNaiveSeam = () => {
    for (const b of [b1, b2]) {
      if (neon.collides(state.ball, b)) {
        state.ball.vx *= -1;
      }
    }
  };

  simulateNaiveSeam();
  assert.strictEqual(Math.sign(state.ball.vx), neon.LEFT, 'Ball should have rebounded from the seam');
});

test('D4: Face vs Coin - Naive fix ignores X axis on corner hit', () => {
  const state = neon.createState(1);
  const brick = neon.makeBricks(1)[0];
  state.ball.x = brick.x - neon.BALL_R / 2;
  state.ball.y = brick.y - neon.BALL_R / 2;
  state.ball.vx = 200;
  state.ball.vy = 200;

  // Naive fix: only flip vy
  const simulateNaiveCorner = () => {
    if (neon.collides(state.ball, brick)) {
      state.ball.vy *= -1;
    }
  };

  simulateNaiveCorner();
  assert.strictEqual(Math.sign(state.ball.vx), neon.LEFT, 'Ball should have rebounded on X axis for corner hit');
});

# to_fix.md

Symptôme : « la balle traverse les briques au lieu de rebondir »

## D1 — Absence de rebond
- **Famille** : Traversée / Missing Logic
- **Symptôme joueur** : la balle traverse les briques
- **Cause** : `game/neon.js:232` — la collision est détectée et la brique détruite, mais aucune modification de la vitesse de la balle n'est appliquée.
- **Invariant violé** : Tout contact avec une brique doit provoquer un rebond.
- **Déclencheur** : N'importe quelle collision balle-brique.
- **Attendu** : La composante de vitesse perpendiculaire à la face touchée doit être inversée.
- **Référence** : https://learnopengl.com/In-Practice/2D-Collision-Resolution
- **Cas test** :
  ```js
  test('D1: Missing bounce', () => {
    const state = neon.createState(1);
    const brick = neon.makeBricks(1)[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y - neon.BALL_R - 1;
    state.ball.vy = 200;
    // Simulate collision...
    assert.strictEqual(Math.sign(state.ball.vy), neon.UP);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced UP`
- **Discrimine** : Refuse l'absence totale de rebond.
- **Vert quand** : La vitesse `vy` est inversée lors d'un impact supérieur.

## D2 — Collision collante (Sticky)
- **Famille** : Collant
- **Symptôme joueur** : La balle semble vibrer ou rester collée à l'intérieur d'une brique.
- **Cause** : Inversion de la vitesse sans repositionnement de la balle hors de l'obstacle.
- **Invariant violé** : Après résolution, la balle doit être hors du rectangle de la brique.
- **Déclencheur** : Collision avec un `dt` ou une vitesse telle que la balle reste en recouvrement après l'inversion de la vitesse.
- **Attendu** : La balle est repositionnée sur le bord de la brique.
- **Référence** : https://manbeardgames.github.io/collision-detection/aabb-collision/
- **Cas test** :
  ```js
  test('D2: Sticky collision', () => {
    const state = neon.createState(1);
    const brick = neon.makeBricks(1)[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y + 1; // Déjà en recouvrement
    // ... bounce logic ...
    assert.ok(!neon.collides(state.ball, brick), 'Ball must be outside the brick after resolution');
  });
  ```
- **Rouge aujourd'hui** : (Sera rouge car aucune résolution n'est implémentée)
- **Discrimine** : Refuse le simple `vy = -vy` sans repositionnement.
- **Vert quand** : `collides(ball, brick)` est faux immédiatement après le rebond.

## D3 — Double inversion aux coutures (Seams)
- **Famille** : Double inversion
- **Symptôme joueur** : La balle traverse une rangée ou une colonne de briques.
- **Cause** : La balle touche deux briques adjacentes dans la même frame, inversant deux fois la même composante de vitesse.
- **Invariant violé** : Un seul rebond par axe par frame.
- **Déclencheur** : Position de la balle sur la couture entre deux briques.
- **Attendu** : La vitesse n'est inversée qu'une seule fois.
- **Référence** : "tile seam ghost collision"
- **Cas test** :
  ```js
  test('D3: Double inversion', () => {
    const state = neon.createState(1);
    const bricks = neon.makeBricks(1);
    state.ball.x = bricks[0].x + bricks[0].w; // Sur la couture
    state.ball.y = bricks[0].y + bricks[0].h / 2;
    state.ball.vx = 200;
    // ... simulate frame ...
    assert.strictEqual(Math.sign(state.ball.vx), neon.LEFT);
  });
  ```
- **Rouge aujourd'hui** : (Sera rouge car aucune logique de rebond n'est implémentée)
- **Discrimine** : Refuse l'application naïve du rebond pour chaque brique touchée sans filtrage.
- **Vert quand** : La vitesse est inversée une seule fois même si deux briques sont touchées.

## D4 — Résolution Face vs Coin
- **Famille** : Face vs coin
- **Symptôme joueur** : Rebonds anormaux lors d'un impact sur l'angle d'une brique.
- **Cause** : Utilisation d'un axe de rebond fixe ou erroné au lieu de l'axe de moindre pénétration.
- **Invariant violé** : L'axe de rebond correspond à la face la plus proche.
- **Déclencheur** : Impact sur le coin d'une brique (pénétrations X et Y similaires).
- **Attendu** : Les deux composantes `vx` et `vy` sont inversées pour un impact de coin.
- **Référence** : "AABB corner resolution"
- **Cas test** :
  ```js
  test('D4: Face vs Coin', () => {
    const state = neon.createState(1);
    const brick = neon.makeBricks(1)[0];
    state.ball.x = brick.x - neon.BALL_R / 2;
    state.ball.y = brick.y - neon.BALL_R / 2;
    state.ball.vx = 200;
    state.ball.vy = 200;
    // ... simulate collision ...
    assert.strictEqual(Math.sign(state.ball.vx), neon.LEFT);
    assert.strictEqual(Math.sign(state.ball.vy), neon.UP);
  });
  ```
- **Rouge aujourd'hui** : (Sera rouge car aucune logique de rebond n'est implémentée)
- **Discrimine** : Refuse l'inversion d'un seul axe lors d'un impact de coin.
- **Vert quand** : `vx` et `vy` sont tous deux inversés.

