// Handles brick collisions: updates score, combo, and ball velocity.
export function handleBrickCollisions(state) {
  const { ball } = state;

  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      // Determine the axis of least penetration to find the hit face.
      const overlapX = Math.min(
        (ball.x + ball.r) - brick.x,
        (brick.x + brick.w) - (ball.x - ball.r)
      );
      const overlapY = Math.min(
        (ball.y + ball.r) - brick.y,
        (brick.y + brick.h) - (ball.y - ball.r)
      );

      if (overlapX < overlapY) {
        // Hit side (Left or Right)
        ball.vx *= -1;
        ball.x += (ball.vx > 0) ? (brick.x + brick.w - (ball.x - ball.r)) : (brick.x - (ball.x + ball.r));
      } else if (overlapY < overlapX) {
        // Hit top or bottom
        ball.vy *= -1;
        ball.y += (ball.vy > 0) ? (brick.y + brick.h - (ball.y - ball.r)) : (brick.y - (ball.y + ball.r));
      } else {
        // Corner hit: flip both
        ball.vx *= -1;
        ball.vy *= -1;
        // Rough corner resolution: move ball just outside the brick
        if (ball.vx > 0) ball.x = brick.x - ball.r - 0.1; else ball.x = brick.x + brick.w + 0.1;
        if (ball.vy > 0) ball.y = brick.y - ball.r - 0.1; else ball.y = brick.y + brick.h + 0.1;
      }

      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }
}

